function Lub_Quat:slerp(b, t)
	local d = self:dot(b)
	local bx = b.x
	local by = b.y
	local bz = b.z
	local bw = b.w
	if d < 0 then
		d = -d
		bx = -bx
		by = -by
		bz = -bz
		bw = -bw
	end
	if d > 0.9995 then
		return Lub_Quat.new(
			self.x + (bx - self.x) * t,
			self.y + (by - self.y) * t,
			self.z + (bz - self.z) * t,
			self.w + (bw - self.w) * t
		):normalize()
	end
	local theta = math.atan(math.sqrt(1.0 - d * d), d)
	local sinT = math.sin(theta)
	local s0 = math.sin((1.0 - t) * theta) / sinT
	local s1 = math.sin(t * theta) / sinT
	return Lub_Quat.new(self.x * s0 + bx * s1, self.y * s0 + by * s1, self.z * s0 + bz * s1, self.w * s0 + bw * s1)
end

function Lub_Quat:rotate_vec3(v)
	local qv = Lub_Vec3.new(self.x, self.y, self.z)
	local uv = qv:cross(v)
	local uuv = qv:cross(uv)
	return v:add(uv:scale(2.0 * self.w):add(uuv:scale(2.0)))
end

function Lub_Quat:to_mat4()
	local x2 = self.x + self.x
	local y2 = self.y + self.y
	local z2 = self.z + self.z
	local xx = self.x * x2
	local xy = self.x * y2
	local xz = self.x * z2
	local yy = self.y * y2
	local yz = self.y * z2
	local zz = self.z * z2
	local wx = self.w * x2
	local wy = self.w * y2
	local wz = self.w * z2
	local r = Lub_Mat4.zero()
	r.m[0 + 1] = 1 - (yy + zz)
	r.m[1 + 1] = xy - wz
	r.m[2 + 1] = xz + wy
	r.m[3 + 1] = 0
	r.m[4 + 1] = xy + wz
	r.m[5 + 1] = 1 - (xx + zz)
	r.m[6 + 1] = yz - wx
	r.m[7 + 1] = 0
	r.m[8 + 1] = xz - wy
	r.m[9 + 1] = yz + wx
	r.m[10 + 1] = 1 - (xx + yy)
	r.m[11 + 1] = 0
	r.m[12 + 1] = 0
	r.m[13 + 1] = 0
	r.m[14 + 1] = 0
	r.m[15 + 1] = 1
	return r
end

function Lub_Quat.from_mat4(m)
	local trace = m.m[0 + 1] + m.m[5 + 1] + m.m[10 + 1]
	if trace > 0 then
		local s = 0.5 / math.sqrt(trace + 1.0)
		return Lub_Quat.new(
			(m.m[9 + 1] - m.m[6 + 1]) * s,
			(m.m[2 + 1] - m.m[8 + 1]) * s,
			(m.m[4 + 1] - m.m[1 + 1]) * s,
			0.25 / s
		)
	elseif m.m[0 + 1] > m.m[5 + 1] and m.m[0 + 1] > m.m[10 + 1] then
		local s = 2.0 * math.sqrt(1.0 + m.m[0 + 1] - m.m[5 + 1] - m.m[10 + 1])
		return Lub_Quat.new(
			0.25 * s,
			(m.m[1 + 1] + m.m[4 + 1]) / s,
			(m.m[8 + 1] + m.m[2 + 1]) / s,
			(m.m[9 + 1] - m.m[6 + 1]) / s
		)
	elseif m.m[5 + 1] > m.m[10 + 1] then
		local s = 2.0 * math.sqrt(1.0 + m.m[5 + 1] - m.m[0 + 1] - m.m[10 + 1])
		return Lub_Quat.new(
			(m.m[1 + 1] + m.m[4 + 1]) / s,
			0.25 * s,
			(m.m[6 + 1] + m.m[9 + 1]) / s,
			(m.m[2 + 1] - m.m[8 + 1]) / s
		)
	else
		local s = 2.0 * math.sqrt(1.0 + m.m[10 + 1] - m.m[0 + 1] - m.m[5 + 1])
		return Lub_Quat.new(
			(m.m[8 + 1] + m.m[2 + 1]) / s,
			(m.m[6 + 1] + m.m[9 + 1]) / s,
			0.25 * s,
			(m.m[4 + 1] - m.m[1 + 1]) / s
		)
	end
end

function Lub_Quat:wire()
	return { x = self.x, y = self.y, z = self.z, w = self.w }
end

function Lub_Quat.from_wire(q)
	return Lub_Quat.new(q.x, q.y, q.z, q.w)
end

function Lub_Quat.__mul_1(a, b)
	return a:mul(b)
end

function Lub_Quat.__mul_2(q, v)
	return q:rotate_vec3(v)
end

Lub_Mat4 = {}
