end

function Lub_Mat4:transpose()
	local r = Lub_Mat4.zero()
	for row = 0, 4 - 1 do
		for col = 0, 4 - 1 do
			r.m[col * 4 + row + 1] = self.m[row * 4 + col + 1]
		end
	end
	return r
end

function Lub_Mat4:determinant()
	local a = self.m
	local a00 = a[0 + 1]
	local a01 = a[1 + 1]
	local a02 = a[2 + 1]
	local a03 = a[3 + 1]
	local a10 = a[4 + 1]
	local a11 = a[5 + 1]
	local a12 = a[6 + 1]
	local a13 = a[7 + 1]
	local a20 = a[8 + 1]
	local a21 = a[9 + 1]
	local a22 = a[10 + 1]
	local a23 = a[11 + 1]
	local a30 = a[12 + 1]
	local a31 = a[13 + 1]
	local a32 = a[14 + 1]
	local a33 = a[15 + 1]
	return a00 * (a11 * (a22 * a33 - a23 * a32) - a12 * (a21 * a33 - a23 * a31) + a13 * (a21 * a32 - a22 * a31))
		- a01 * (a10 * (a22 * a33 - a23 * a32) - a12 * (a20 * a33 - a23 * a30) + a13 * (a20 * a32 - a22 * a30))
		+ a02 * (a10 * (a21 * a33 - a23 * a31) - a11 * (a20 * a33 - a23 * a30) + a13 * (a20 * a31 - a21 * a30))
		- a03 * (a10 * (a21 * a32 - a22 * a31) - a11 * (a20 * a32 - a22 * a30) + a12 * (a20 * a31 - a21 * a30))
end

function Lub_Mat4:inverse()
	local a = self.m
	local a00 = a[0 + 1]
	local a01 = a[1 + 1]
	local a02 = a[2 + 1]
	local a03 = a[3 + 1]
	local a10 = a[4 + 1]
	local a11 = a[5 + 1]
	local a12 = a[6 + 1]
	local a13 = a[7 + 1]
	local a20 = a[8 + 1]
	local a21 = a[9 + 1]
	local a22 = a[10 + 1]
	local a23 = a[11 + 1]
	local a30 = a[12 + 1]
	local a31 = a[13 + 1]
	local a32 = a[14 + 1]
	local a33 = a[15 + 1]
	local b00 = a00 * a11 - a01 * a10
	local b01 = a00 * a12 - a02 * a10
	local b02 = a00 * a13 - a03 * a10
	local b03 = a01 * a12 - a02 * a11
	local b04 = a01 * a13 - a03 * a11
	local b05 = a02 * a13 - a03 * a12
	local b06 = a20 * a31 - a21 * a30
	local b07 = a20 * a32 - a22 * a30
	local b08 = a20 * a33 - a23 * a30
	local b09 = a21 * a32 - a22 * a31
	local b10 = a21 * a33 - a23 * a31
	local b11 = a22 * a33 - a23 * a32
	local det = b00 * b11 - b01 * b10 + b02 * b09 + b03 * b08 - b04 * b07 + b05 * b06
	if det == 0 then
		return Lub_Mat4.identity()
	end
	local inv = 1.0 / det
	local r = Lub_Mat4.zero()
	r.m[0 + 1] = (a11 * b11 - a12 * b10 + a13 * b09) * inv
	r.m[1 + 1] = (-a01 * b11 + a02 * b10 - a03 * b09) * inv
	r.m[2 + 1] = (a31 * b05 - a32 * b04 + a33 * b03) * inv
	r.m[3 + 1] = (-a21 * b05 + a22 * b04 - a23 * b03) * inv
	r.m[4 + 1] = (-a10 * b11 + a12 * b08 - a13 * b07) * inv
	r.m[5 + 1] = (a00 * b11 - a02 * b08 + a03 * b07) * inv
	r.m[6 + 1] = (-a30 * b05 + a32 * b02 - a33 * b01) * inv
	r.m[7 + 1] = (a20 * b05 - a22 * b02 + a23 * b01) * inv
	r.m[8 + 1] = (a10 * b10 - a11 * b08 + a13 * b06) * inv
	r.m[9 + 1] = (-a00 * b10 + a01 * b08 - a03 * b06) * inv
	r.m[10 + 1] = (a30 * b04 - a31 * b02 + a33 * b00) * inv
	r.m[11 + 1] = (-a20 * b04 + a21 * b02 - a23 * b00) * inv
	r.m[12 + 1] = (-a10 * b09 + a11 * b07 - a12 * b06) * inv
	r.m[13 + 1] = (a00 * b09 - a01 * b07 + a02 * b06) * inv
	r.m[14 + 1] = (-a30 * b03 + a31 * b01 - a32 * b00) * inv
	r.m[15 + 1] = (a20 * b03 - a21 * b01 + a22 * b00) * inv
	return r
end

function Lub_Mat4:rigid_inverse(eye)
	local r = Lub_Mat4.zero()
	r.m[0 + 1] = self.m[0 + 1]
	r.m[1 + 1] = self.m[4 + 1]
	r.m[2 + 1] = self.m[8 + 1]
	r.m[3 + 1] = eye.x
	r.m[4 + 1] = self.m[1 + 1]
	r.m[5 + 1] = self.m[5 + 1]
	r.m[6 + 1] = self.m[9 + 1]
	r.m[7 + 1] = eye.y
	r.m[8 + 1] = self.m[2 + 1]
	r.m[9 + 1] = self.m[6 + 1]
	r.m[10 + 1] = self.m[10 + 1]
	r.m[11 + 1] = eye.z
	r.m[12 + 1] = 0
	r.m[13 + 1] = 0
	r.m[14 + 1] = 0
	r.m[15 + 1] = 1
	return r
end

