function Lubx_Assets.shader(key, vsPath, fsPath)
	local vs
	local vsVersion
	local _
	vs, vsVersion, _, _ = lub.io.load_text(vsPath)
	local fs
	local fsVersion
	local _
	fs, fsVersion, _, _ = lub.io.load_text(fsPath)
	if vs == nil or fs == nil then
		return nil
	end
	return lub.gfx.use_shader(key, vs, fs, vsVersion * 31 + fsVersion)
end

function Lubx_Assets.wav(key, path)
	local bytes
	local version
	local _
	bytes, version, _, _ = lub.io.load_bytes(path)
	if bytes == nil then
		return nil
	end
	local e
	if
		(function()
			local __tcs_found, __tcs_v = Dict.TryGet(Lubx_Assets.wavs, key, nil)
			e = __tcs_v
			return __tcs_found
		end)() and e.version == version
