		else
			live = nil
		end
		if live ~= nil and (live.version == claim) then
			self.texture = lub.gfx.use_texture(self.key, self.w, self.h, self.format, nil, claim, self:texture_opts())
		else
			self.texture = lub.gfx.use_texture(
				self.key,
				self.w,
				self.h,
				self.format,
				self.pixels,
				self.version,
				self:texture_opts()
			)
