	local count = 0
	if mesh ~= nil and mesh.bones ~= nil then
		local bones = mesh.bones
		local n = #bones
		local i = 0
		while count < 16 and i < n do
			local b = bones[i + 1]
			local m = resolve(b.name, b.x, b.y, b.z)
			if m == nil then
				m = Lub_Mat4.new()
			end
			for _, v in ipairs(m.m) do
				arr[#arr + 1] = v
