function Lubx_FixedStep.new(hz, maxCatchUp)
	local self = setmetatable({
		tick_dt = 0,
		max_catch_up = 0,
		accumulator = 0,
		stopped = false,
		pending_key_pressed = {},
		pending_key_released = {},
